/// Spacing scale, named by pixel value (`s16` = 16).
abstract final class FtSpacing {
  /// Gap between a card title and its meta line.
  static const double s2 = 2;
  /// Small button vertical padding, icon–label gap in Small buttons.
  static const double s4 = 4;
  /// Medium button vertical padding, gap inside rows.
  static const double s8 = 8;
  /// Toolbar bottom inset. Off the 4pt grid — avoid in new work.
  static const double s10 = 10;
  /// Card vertical padding, gap between chip and text in SessionCard, Small button horizontal padding.
  static const double s12 = 12;
  /// Large button vertical padding. Off the 4pt grid — avoid in new work.
  static const double s14 = 14;
  /// Screen side gutter, card horizontal padding, Medium button horizontal padding.
  static const double s16 = 16;
  /// Spacing step (unused today).
  static const double s20 = 20;
  /// Gap between sections; Large button horizontal padding.
  static const double s24 = 24;
  /// Spacing step.
  static const double s32 = 32;
  /// Spacing step (unused today).
  static const double s40 = 40;
  /// Spacing step (unused today).
  static const double s56 = 56;
  /// Spacing step (unused today).
  static const double s72 = 72;
}

/// Corner radii.
abstract final class FtRadius {
  /// Square corners.
  static const double none = 0;
  /// Small elements.
  static const double sm = 4;
  /// `SessionCard` type chip, Home stat icon tiles.
  static const double md = 8;
  /// SessionCard, list cards.
  static const double lg = 12;
  /// Large containers.
  static const double xl = 16;
  /// Sheets and the Bankroll card.
  static const double xxl = 24;
  /// Buttons, chips, swatches, tab bar, progress bars.
  static const double full = 999;
}

/// Icon sizes and the 44pt minimum hit target.
abstract final class FtSize {
  /// Icon in Small buttons.
  static const double iconXs = 14;
  /// Icon in Medium buttons.
  static const double iconSm = 16;
  /// Icon in Large buttons; Bankroll eye toggle.
  static const double iconMd = 20;
  /// SessionCard type-chip icons.
  static const double iconLg = 24;
  /// Tab bar icons.
  static const double iconXl = 28;
  /// Top-bar icon buttons.
  static const double iconXxl = 32;
  /// Minimum tappable area (Apple HIG 44×44 pt).
  static const double hitTarget = 44;
}

/// Stroke widths.
abstract final class FtBorderWidth {
  /// Card borders, dividers, text-field outlines.
  static const double hairline = 1;
  /// Selected ring (ColorSwatch).
  static const double selected = 2;
  /// Focus ring width.
  static const double focus = 3;
}

/// Opacity applied on top of a colour token.
abstract final class FtOpacity {
  /// Tab bar glass wash (label-primary at 3%).
  static const double glass = 0.03;
  /// Tab bar "+" button glass wash.
  static const double glassStrong = 0.05;
  /// Empty progress-track outline.
  static const double trackEmpty = 0.25;
}

/// Elevation shadows (neutral black). The focus ring follows the theme,
/// so build it from `FtColors.focusRing` with [FtShadows.focusRing].
abstract final class FtShadows {
  /// Elevation/Low effect style.
  static const List<BoxShadow> elevationLow = [
    BoxShadow(color: Color(0x0F000000), offset: Offset(0, 1), blurRadius: 2, spreadRadius: 0),
    BoxShadow(color: Color(0x0A000000), offset: Offset(0, 1), blurRadius: 1, spreadRadius: 0),
  ];

  /// Elevation/Medium effect style.
  static const List<BoxShadow> elevationMedium = [
    BoxShadow(color: Color(0x14000000), offset: Offset(0, 4), blurRadius: 8, spreadRadius: 0),
    BoxShadow(color: Color(0x0F000000), offset: Offset(0, 2), blurRadius: 4, spreadRadius: 0),
  ];

  /// Elevation/High effect style.
  static const List<BoxShadow> elevationHigh = [
    BoxShadow(color: Color(0x1F000000), offset: Offset(0, 12), blurRadius: 24, spreadRadius: 0),
    BoxShadow(color: Color(0x14000000), offset: Offset(0, 4), blurRadius: 8, spreadRadius: 0),
  ];

  /// Elevation/Floating effect style: tab bar and top-bar icon buttons.
  static const List<BoxShadow> floatingBar = [
    BoxShadow(color: Color(0x1F000000), offset: Offset(0, 8), blurRadius: 40, spreadRadius: 0),
  ];

  /// 3px focus ring in the theme's `focusRing` colour.
  static List<BoxShadow> focusRing(FtColors c) => [
        BoxShadow(color: c.focusRing, spreadRadius: FtBorderWidth.focus),
      ];
}

